from pathlib import Path

js_path = Path('workspace/shared/ticketEnterprise.js')
css_path = Path('workspace/shared/portalEnterprise.css')
client_path = Path('workspace/client/ticket.html')
admin_path = Path('workspace/admin/ticketAdmin.html')

js = js_path.read_text(encoding='utf-8')
old_markup = '''  function attachmentMarkup(item) {\n    const image = item.contentType?.startsWith('image/');\n    if (image) {\n      return `<a class="attachment-preview" href="${escapeHtml(item.downloadUrl)}" target="_blank" rel="noopener" title="Abrir ${escapeHtml(item.fileName)}">\n        <img src="${escapeHtml(item.downloadUrl)}" alt="${escapeHtml(item.fileName)}" loading="lazy">\n        <span><strong>${escapeHtml(item.fileName)}</strong><small>${formatBytes(item.size)} • ver original</small></span>\n      </a>`;\n    }\n    return `<a class="attachment-file" href="${escapeHtml(item.downloadUrl)}" target="_blank" rel="noopener">\n      <i class="bi bi-file-earmark-pdf"></i><span><strong>${escapeHtml(item.fileName)}</strong><small>${formatBytes(item.size)} • PDF</small></span><i class="bi bi-box-arrow-up-right"></i>\n    </a>`;\n  }\n'''
new_markup = '''  function attachmentMarkup(item) {\n    const image = item.contentType?.startsWith('image/');\n    if (image) {\n      return `<button class="attachment-preview attachment-image-open" type="button" data-image-preview="1" data-image-src="${escapeHtml(item.downloadUrl)}" data-image-name="${escapeHtml(item.fileName)}" data-image-size="${escapeHtml(formatBytes(item.size))}" title="Visualizar ${escapeHtml(item.fileName)}">\n        <img src="${escapeHtml(item.downloadUrl)}" alt="${escapeHtml(item.fileName)}" loading="lazy">\n        <span><strong>${escapeHtml(item.fileName)}</strong><small>${formatBytes(item.size)}</small></span>\n        <i class="bi bi-arrows-fullscreen attachment-preview-open-icon" aria-hidden="true"></i>\n      </button>`;\n    }\n    return `<a class="attachment-file" href="${escapeHtml(item.downloadUrl)}" target="_blank" rel="noopener">\n      <i class="bi bi-file-earmark-pdf"></i><span><strong>${escapeHtml(item.fileName)}</strong><small>${formatBytes(item.size)} • PDF</small></span><i class="bi bi-box-arrow-up-right"></i>\n    </a>`;\n  }\n\n  function ensureImageModal() {\n    let modal = document.getElementById('attachmentImageModal');\n    if (modal) return modal;\n    modal = document.createElement('div');\n    modal.id = 'attachmentImageModal';\n    modal.className = 'attachment-image-modal';\n    modal.hidden = true;\n    modal.innerHTML = `<div class="attachment-image-modal-backdrop" data-image-modal-close></div>\n      <div class="attachment-image-modal-card" role="dialog" aria-modal="true" aria-labelledby="attachmentImageModalTitle">\n        <div class="attachment-image-modal-head">\n          <div><small>ANEXO DO CHAMADO</small><strong id="attachmentImageModalTitle">Imagem</strong><span id="attachmentImageModalSize"></span></div>\n          <button type="button" class="attachment-image-modal-close" data-image-modal-close aria-label="Fechar imagem"><i class="bi bi-x-lg"></i></button>\n        </div>\n        <div class="attachment-image-modal-body"><img id="attachmentImageModalPreview" alt=""></div>\n      </div>`;\n    document.body.appendChild(modal);\n    modal.addEventListener('click', event => {\n      if (event.target.closest('[data-image-modal-close]')) closeImageModal();\n    });\n    return modal;\n  }\n  function openImageModal(trigger) {\n    const modal = ensureImageModal();\n    const image = modal.querySelector('#attachmentImageModalPreview');\n    const title = modal.querySelector('#attachmentImageModalTitle');\n    const size = modal.querySelector('#attachmentImageModalSize');\n    const src = trigger.dataset.imageSrc || '';\n    const name = trigger.dataset.imageName || 'Imagem';\n    image.src = src;\n    image.alt = name;\n    title.textContent = name;\n    size.textContent = trigger.dataset.imageSize || '';\n    modal.hidden = false;\n    requestAnimationFrame(() => modal.classList.add('open'));\n    document.body.classList.add('attachment-modal-open');\n    modal.querySelector('.attachment-image-modal-close')?.focus();\n  }\n  function closeImageModal() {\n    const modal = document.getElementById('attachmentImageModal');\n    if (!modal || modal.hidden) return;\n    modal.classList.remove('open');\n    document.body.classList.remove('attachment-modal-open');\n    setTimeout(() => {\n      modal.hidden = true;\n      const image = modal.querySelector('#attachmentImageModalPreview');\n      if (image) image.src = '';\n    }, 180);\n  }\n  function bindImageModal() {\n    if (document.documentElement.dataset.attachmentModalBound === '1') return;\n    document.documentElement.dataset.attachmentModalBound = '1';\n    document.addEventListener('click', event => {\n      const trigger = event.target.closest('[data-image-preview="1"]');\n      if (!trigger) return;\n      event.preventDefault();\n      openImageModal(trigger);\n    });\n    document.addEventListener('keydown', event => {\n      if (event.key === 'Escape') closeImageModal();\n    });\n  }\n'''
if old_markup not in js:
    raise SystemExit('attachment markup block not found')
js = js.replace(old_markup, new_markup)
js = js.replace("    bindAttachmentInputs();\n    refreshAttachments();", "    bindAttachmentInputs();\n    bindImageModal();\n    refreshAttachments();")
js_path.write_text(js, encoding='utf-8')

css = css_path.read_text(encoding='utf-8')
css += '''\n.attachment-image-open{font:inherit;text-align:left;cursor:pointer;width:100%;appearance:none;-webkit-appearance:none}.attachment-preview-open-icon{flex:0 0 auto;margin-right:4px;color:#174f82;font-size:14px}.attachment-modal-open{overflow:hidden}.attachment-image-modal[hidden]{display:none}.attachment-image-modal{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;padding:24px;opacity:0;transition:opacity .18s ease}.attachment-image-modal.open{opacity:1}.attachment-image-modal-backdrop{position:absolute;inset:0;background:rgba(8,20,32,.72);backdrop-filter:blur(7px)}.attachment-image-modal-card{position:relative;z-index:1;width:min(980px,94vw);max-height:90vh;display:flex;flex-direction:column;overflow:hidden;border-radius:20px;background:#fff;box-shadow:0 28px 80px rgba(0,0,0,.35);transform:translateY(12px) scale(.985);transition:transform .18s ease}.attachment-image-modal.open .attachment-image-modal-card{transform:translateY(0) scale(1)}.attachment-image-modal-head{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 18px;border-bottom:1px solid #e7edf2;background:#fff}.attachment-image-modal-head>div{min-width:0;display:grid;gap:2px}.attachment-image-modal-head small{font-size:9px;font-weight:800;letter-spacing:.1em;color:#7f8a94}.attachment-image-modal-head strong{max-width:min(720px,70vw);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;color:#21313d}.attachment-image-modal-head span{font-size:10px;color:#87939d}.attachment-image-modal-close{width:40px;height:40px;display:grid;place-items:center;flex:0 0 auto;border:1px solid #dbe4eb;border-radius:11px;background:#f8fafc;color:#24333f;cursor:pointer;font-size:17px;transition:.16s ease}.attachment-image-modal-close:hover{background:#edf4fa;color:#174f82;border-color:#c8dbea}.attachment-image-modal-body{min-height:260px;display:grid;place-items:center;overflow:auto;padding:18px;background:#0d1720}.attachment-image-modal-body img{display:block;max-width:100%;max-height:calc(90vh - 110px);width:auto;height:auto;object-fit:contain;border-radius:10px;box-shadow:0 12px 34px rgba(0,0,0,.24)}@media(max-width:700px){.attachment-image-modal{padding:10px}.attachment-image-modal-card{width:100%;max-height:94vh;border-radius:16px}.attachment-image-modal-head{padding:13px}.attachment-image-modal-head strong{max-width:68vw}.attachment-image-modal-body{padding:10px}.attachment-image-modal-body img{max-height:calc(94vh - 96px)}}\n'''
css_path.write_text(css, encoding='utf-8')

client = client_path.read_text(encoding='utf-8')
client = client.replace('<small class="storage-warning" data-attachment-storage-state hidden>Anexos aguardando configuração do storage privado.</small>', '')
client_path.write_text(client, encoding='utf-8')

admin = admin_path.read_text(encoding='utf-8')
admin = admin.replace('<small class="storage-warning" data-attachment-storage-state hidden>Storage privado ainda não configurado.</small>', '')
admin_path.write_text(admin, encoding='utf-8')

print('Attachment modal patch applied')
